SET LOCAL lock_timeout='750ms';SET LOCAL statement_timeout='180s';SET LOCAL work_mem='64MB';SET LOCAL jit='off';SET LOCAL enable_nestloop='off';SET LOCAL jit='off';SET LOCAL enable_nestloop='off';SET LOCAL jit='off';SET LOCAL enable_nestloop='off';
