 FROM rawpts p JOIN %2$I a USING(company_id) JOIN pdocs sd ON sd.source_id=p.source_id AND sd.ordinal=p.ordinal
)
SELECT company_id,point_date,count(*) n,min(ticker) ticker,min(sr->>'composite_figi') composite_figi,min(sr->>'share_class_figi') share_class_figi,min(sr->>'cik') cik,min(sr->>'type') typ,min(sr->>'primary_exchange') exchange,min(point_sha) point_sha,bool_and(checked) checked FROM pts GROUP BY company_id,point_date$phase$ ,tn_sel,tn_anchors) USING p_first,p_last;
 EXECUTE 'ANALYZE '||quote_ident(tn_pg);
