cal AS MATERIALIZED(SELECT * FROM cal0 WHERE target),
dates AS MATERIALIZED(SELECT d FROM cal UNION SELECT prev FROM cal),
ss AS MATERIALIZED(SELECT s.* FROM population_top3000_202608_202609_v1.daily_shared_series_v1 s WHERE s.run_id='19a35bfa-6023-4092-9809-3ed950871d7f' AND s.source_ticker IN(SELECT ticker FROM %1$I)),
inputs AS MATERIALIZED(SELECT i.source_key,i.source_count,i.source_kind,i.source_record_sha256,i.session_date,i.series_no,i.raw_close,i.split_factor,i.unknown_actions,i.price_basis,i.input_record_sha256,i.identity_anchor,s.source_ticker,s.candidate_snapshot->>'composite_figi' candidate_composite,s.candidate_snapshot->>'share_class_figi' candidate_share,s.candidate_snapshot->>'cik_candidate' candidate_cik,s.candidate_snapshot->>'source_type' candidate_type,s.candidate_snapshot->>'primary_exchange' candidate_exchange,s.derived_at,s.output_rows,population_top3000_202608_202609_v1.ctx06_observed_check_v4(i.input_record_sha256=sha256(convert_to(((to_jsonb(i)-'run_id'-'series_no'-'input_record_sha256')||jsonb_build_object('source_record_sha256',encode(i.source_record_sha256,'hex'),'identity_record_sha256',encode(i.identity_record_sha256,'hex'),'action_record_sha256',encode(i.action_record_sha256,'hex')))::text,'UTF8')),'DAILY_INPUT_HASH') checked FROM population_top3000_202608_202609_v1.daily_shared_input_v1 i JOIN ss s USING(run_id,series_no) JOIN dates c ON c.d=i.session_date),
ddays AS MATERIALIZED(SELECT ds.* FROM population_top3000_202608_202609_v1.d02_daily_source_v2 ds WHERE ds.session_date IN(SELECT d FROM dates)),
bars AS MATERIALIZED(SELECT b.*,count(*)OVER(PARTITION BY b.source_day_id,b.source_ticker) n,sha256(convert_to(to_jsonb(b)::text,'UTF8')) typed_sha FROM population_top3000_202608_202609_v1.d02_daily_bar_v2 b WHERE b.source_day_id IN(SELECT source_day_id FROM ddays) AND b.source_ticker IN(SELECT source_ticker FROM ss)),
dreq AS MATERIALIZED(SELECT source_day_id,jsonb_object_agg(source_row::text,true) om FROM bars GROUP BY source_day_id),
dchecks AS MATERIALIZED(SELECT ds.source_day_id,ds.source_id,ds.source_sha256,ds.session_date,population_top3000_202608_202609_v1.ctx06_observed_check_v4(ds.source_sha256=sd.source_sha256 AND sd.source_sha256=encode(sha256(convert_to(sd.content_text,'UTF8')),'hex') AND sd.content_bytes=octet_length(sd.content_text),'DAILY_BODY') checked FROM dreq req JOIN ddays ds USING(source_day_id) JOIN population_top3000_202608_202609_v1.source_document sd USING(source_id)),
ddocs AS MATERIALIZED(SELECT ch.source_day_id,ch.source_id,ch.source_sha256,ch.session_date,x.ord::int source_row,sha256(convert_to(x.rec::text,'UTF8')) raw_sha,x.rec->>'T' raw_ticker,CASE WHEN jsonb_typeof(x.rec->'c')='number' THEN (x.rec->>'c')::numeric END raw_close,CASE WHEN jsonb_typeof(x.rec->'t')='number' THEN (x.rec->>'t')::numeric END raw_time,ch.checked FROM dreq req JOIN dchecks ch USING(source_day_id) JOIN population_top3000_202608_202609_v1.source_document sd USING(source_id) CROSS JOIN LATERAL jsonb_array_elements(sd.content_text::jsonb->'results')WITH ORDINALITY x(rec,ord) WHERE req.om ? x.ord::text)
SELECT i.source_ticker,i.session_date,i.series_no,i.raw_close,i.split_factor,i.unknown_actions,i.price_basis,i.source_count,i.source_kind,i.input_record_sha256,i.derived_at,i.output_rows,i.identity_anchor,i.candidate_composite,i.candidate_share,i.candidate_cik,i.candidate_type,i.candidate_exchange,CASE WHEN i.source_count=1 AND i.source_kind=2 THEN population_top3000_202608_202609_v1.ctx06_observed_check_v4(i.checked AND ds.checked AND b.n=1 AND i.source_key=ds.source_id||':'||b.source_row::text AND b.raw_record_sha256=ds.raw_sha AND b.source_ticker=ds.raw_ticker AND b.provider_close IS NOT DISTINCT FROM ds.raw_close AND b.provider_time_ms IS NOT DISTINCT FROM ds.raw_time AND b.provider_ny_date=i.session_date AND i.raw_close IS NOT DISTINCT FROM CASE WHEN (b.missing_mask&35)=0 AND (b.invalid_mask&63)=0 AND b.structure_mask=0 THEN b.provider_close END AND i.source_record_sha256=sha256(convert_to(jsonb_build_object('source_id',ds.source_id,'source_sha256',ds.source_sha256,'selected_typed_rows_sha256',encode(sha256(convert_to(encode(b.typed_sha,'hex'),'UTF8')),'hex'),'source_count_capped_at_two',1)::text,'UTF8')),'DAILY_TYPED_SOURCE') ELSE i.checked END valid FROM inputs i LEFT JOIN ddays dy ON dy.session_date=i.session_date LEFT JOIN bars b ON b.source_day_id=dy.source_day_id AND b.source_ticker=i.source_ticker AND i.source_key=dy.source_id||':'||b.source_row::text LEFT JOIN ddocs ds ON ds.source_day_id=b.source_day_id AND ds.source_row=b.source_row$phase$ ,tn_pg) USING p_first,p_last;
 EXECUTE 'ANALYZE '||quote_ident(tn_iok);
 stage_bytes:=stage_bytes+pg_total_relation_size(tn_iok::regclass);
 SELECT coalesce(sum(pg_total_relation_size(c.oid)),0) INTO permanent_bytes FROM pg_class c WHERE c.relnamespace='population_top3000_202608_202609_v1'::regnamespace AND c.relname IN('ctx06_observed_run_v4','ctx06_observed_vote_v4','ctx06_observed_session_v4');
 IF stage_bytes+permanent_bytes>134217728 THEN RAISE EXCEPTION 'CTX06_OBSERVED_CUMULATIVE_STAGE_RELATION_BOUND';END IF;
 RETURN QUERY EXECUTE format($final$WITH cal0 AS MATERIALIZED(SELECT (x->>'date')::date d,(x->>'is_target')::boolean target,lag((x->>'date')::date)OVER(ORDER BY x->>'date') prev FROM jsonb_array_elements(population_top3000_202608_202609_v1.daily_shared_calendar_v1()->'sessions')x),
cal AS MATERIALIZED(SELECT * FROM cal0 WHERE target),
dates AS MATERIALIZED(SELECT d FROM cal UNION SELECT prev FROM cal),
grid AS MATERIALIZED(SELECT s.company_ordinal,s.company_id,c.d,c.prev,p.n pn,q.n qn,p.ticker,p.point_sha cp,q.point_sha pp,p.composite_figi,p.share_class_figi,p.cik,p.typ,p.exchange,q.ticker prev_ticker,q.composite_figi prev_composite,q.share_class_figi prev_share,q.cik prev_cik,q.typ prev_type,q.exchange prev_exchange,p.checked pc,q.checked qc FROM %1$I s CROSS JOIN cal c LEFT JOIN %2$I p ON p.company_id=s.company_id AND p.point_date=c.d LEFT JOIN %2$I q ON q.company_id=s.company_id AND q.point_date=c.prev),
joined AS MATERIALIZED(SELECT g.*,i.series_no,i.raw_close cur_close,j.raw_close prev_close,i.split_factor,i.unknown_actions,i.price_basis,j.price_basis prev_basis,i.source_count cur_count,j.source_count prev_count,i.source_kind cur_kind,j.source_kind prev_kind,i.input_record_sha256 ci,j.input_record_sha256 pi,i.valid iv,j.valid jv,i.candidate_composite,i.candidate_share,i.candidate_cik,i.candidate_type,i.candidate_exchange,i.derived_at,i.output_rows,i.identity_anchor ia,j.identity_anchor ja FROM grid g LEFT JOIN %3$I i ON i.source_ticker=g.ticker AND i.session_date=g.d LEFT JOIN %3$I j ON j.series_no=i.series_no AND j.session_date=g.prev),
reasoned AS MATERIALIZED(SELECT *,CASE WHEN pn IS NULL OR qn IS NULL THEN 'NO_QUALIFYING_POINT_IN_BOUND_INPUT_GENERATION' WHEN pn<>1 OR qn<>1 THEN 'AMBIGUOUS_OBSERVED_ANCHOR_POINT' WHEN NOT(pc AND qc) THEN 'INVALID_POINT' WHEN ticker IS DISTINCT FROM prev_ticker OR composite_figi IS DISTINCT FROM prev_composite OR share_class_figi IS DISTINCT FROM prev_share OR cik IS DISTINCT FROM prev_cik OR typ IS DISTINCT FROM prev_type OR exchange IS DISTINCT FROM prev_exchange THEN 'OBSERVED_IDENTITY_OR_TICKER_CHANGED' WHEN typ NOT IN('CS','ADRC') THEN 'INELIGIBLE_OBSERVED_TYPE' WHEN series_no IS NULL THEN 'DAILY_SOURCE_SERIES_MISSING' WHEN nullif(composite_figi,'') IS NULL OR nullif(share_class_figi,'') IS NULL OR candidate_composite IS DISTINCT FROM composite_figi OR candidate_share IS DISTINCT FROM share_class_figi OR candidate_cik IS DISTINCT FROM cik OR candidate_type IS DISTINCT FROM typ OR candidate_exchange IS DISTINCT FROM exchange THEN 'DAILY_CANDIDATE_FIGI_DISAGREEMENT' WHEN cur_count IS DISTINCT FROM 1 OR prev_count IS DISTINCT FROM 1 THEN 'CURRENT_OR_PREVIOUS_DAILY_SOURCE_MISSING_OR_CONFLICT' WHEN cur_kind IS DISTINCT FROM 2 OR prev_kind IS DISTINCT FROM 2 THEN 'RETAINED_TARGET_SOURCE_REQUIRED' WHEN iv IS DISTINCT FROM true OR jv IS DISTINCT FROM true THEN 'DAILY_INPUT_NOT_VERIFIED' WHEN derived_at IS NULL OR output_rows<>42 THEN 'DAILY_CALCULATION_INCOMPLETE' WHEN ia IS NOT NULL AND ia<>share_class_figi OR ja IS NOT NULL AND ja<>share_class_figi THEN 'DAILY_IDENTITY_ANCHOR_CONFLICT' WHEN price_basis IS DISTINCT FROM prev_basis THEN 'PRICE_BASIS_DISAGREEMENT' WHEN unknown_actions IS DISTINCT FROM 0 THEN 'UNRESOLVED_SPLIT_ACTION' WHEN cur_close IS NULL OR prev_close IS NULL OR cur_close NOT BETWEEN 1e-100 AND 1e100 OR prev_close NOT BETWEEN 1e-100 AND 1e100 OR split_factor IS NULL OR split_factor<=1e-20 OR split_factor>=1e20 OR cur_close::text IN('NaN','Infinity','-Infinity') OR prev_close::text IN('NaN','Infinity','-Infinity') OR split_factor::text IN('NaN','Infinity','-Infinity') THEN 'INVALID_CLOSE_OR_SPLIT_FACTOR' WHEN abs(ln(cur_close)+ln(split_factor)-ln(prev_close))>300 THEN 'RETURN_NUMERIC_RANGE' END why FROM joined),
vals AS MATERIALIZED(SELECT company_ordinal,company_id,d session_date,prev previous_session_date,ticker,series_no,CASE WHEN why IS NULL THEN cur_close*split_factor/prev_close-1 END return_1d,why missing_reason,cp current_point_sha256,pp previous_point_sha256,ci current_input_sha256,pi previous_input_sha256 FROM reasoned)
SELECT v.*,encode(sha256(convert_to(to_jsonb(v)::text,'UTF8')),'hex') FROM vals v ORDER BY company_ordinal,session_date;$final$ ,tn_sel,tn_pg,tn_iok) USING p_first,p_last;
 EXECUTE 'DROP TABLE '||quote_ident(tn_sel)||','||quote_ident(tn_pg)||','||quote_ident(tn_iok);
END;
